#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long long n = strtoll(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) { // limit observed in the original binary
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long row[61] = {0};
    for (long long i = 0; i < n; ++i) {
        // compute current row in-place (right‑to‑left)
        row[0] = 1ULL;
        for (long long j = i; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
        // print the row
        for (long long j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%lld", (long long)row[j]);
        }
        putchar('\n');
    }
    return 0;
}
